from pathlib import Path
p=Path('src/pages/manager/OperationsPage.jsx');s=p.read_text(encoding='utf-8');needle="const closed=['COMPLETED','CANCELLED'].includes(task.status);return <Screen";replacement="""const closed=['COMPLETED','CANCELLED'].includes(task.status);if(task.deskId&&['SUPPORT','MAINTENANCE'].includes(task.type)){const collection=task.type==='SUPPORT'?'support':'maintenance',record=data[collection].find(r=>r.id===task.deskId);return <Screen title={`${task.type} · ${task.id}`} code={task.type==='SUPPORT'?'P038 / P045':'P031 / P045'} description=\"Coordinate the assigned staff and open the related operational record.\" action={<OpenLink to=\"/manager/operations\">Daily operations</OpenLink>}><div className=\"grid gap-6 lg:grid-cols-2\"><Panel title=\"Task context\"><Details values={[[\"Task\",task.id],['Resource',task.resource],['Date',task.date],['Task status',<Status value={task.status}/>],['Related record',task.deskId],['Record status',<Status value={record?.status}/>],['Issue / subject',record?.issue||record?.subject]]}/><div className=\"mt-6\"><OpenLink to={`/manager/${collection}/${task.deskId}`}>Open {collection} record</OpenLink></div></Panel><Panel title=\"Staff assignment\"><Assignment key={task.staffId} task={task} data={data}/></Panel></div><Panel title=\"Task timeline\"><Timeline entries={task.timeline}/></Panel></Screen>;}return <Screen""";assert needle in s;s=s.replace(needle,replacement);p.write_text(s,encoding='utf-8')
